import * as fs from "fs";

// 標準入力（左の「入力例」の内容）を 1 つの文字列として受け取り、
// 改行で区切って 1 行ずつの配列にする
const input: string[] = fs.readFileSync(0, "utf8").trim().split("\n");

// 入力例 1 のとき:
//   input[0] は "5"
//   input[1] は "3 -1 0 7 -2"

// 答えは console.log で出力する
// ここに解答を書く

solution.code:
import { readFileSync } from "fs";

const [, second] = readFileSync(0, "utf8").trim().split("\n");
const a = second.split(" ").map(Number);

let positive = 0;
let negative = 0;
let zero = 0;
for (const x of a) {
  if (x > 0) positive++;
  else if (x < 0) negative++;
  else zero++;
}
console.log(positive + " " + negative + " " + zero);
